#Requires -Version 7
# Forwards ADE commands to the shared runtime. Teams do not edit this file; setup.ps1 regenerates it.
$ErrorActionPreference = 'Stop'
$pluginRoot = Split-Path $PSScriptRoot -Parent
$packDir = Join-Path $pluginRoot 'pack'
$version = '0.1.0'

$exe = if ($env:ADE_RUNTIME_DIR) { Join-Path $env:ADE_RUNTIME_DIR 'ade.exe' }
       else { Join-Path $env:LOCALAPPDATA "ade\runtime\$version\ade.exe" }
if (-not (Test-Path $exe)) {
    Write-Output "ADE runtime $version is not installed at $exe. Run setup.ps1 from the ADE platform package."
    Write-Output ('ADE-RESULT: {"command":"launcher","ok":false,"status":"Stopped","stopReason":"EnvironmentFailure","message":"ADE runtime ' + $version + ' not installed"}')
    exit 4
}

$forward = [System.Collections.Generic.List[string]]::new()
$args | ForEach-Object { $forward.Add([string]$_) }
if ($forward.Count -gt 0 -and $forward[0] -in 'propose', 'doctor', 'types', 'workstream' -and -not ($forward -contains '--pack')) {
    $forward.Add('--pack'); $forward.Add($packDir)
}
& $exe @forward
exit $LASTEXITCODE
